def summarize(runs):
    out = {}
    for run in runs:
        row = out.setdefault(
            run["runtime"],
            {"completed": 0, "passed": 0, "execution_errors": 0},
        )
        row["completed"] += 1
        row["passed"] += bool(run["passed"])
    return {"runtimes": out}

